#!/usr/bin/env python3
from __future__ import annotations
import argparse,json,os
from html import escape
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--package-root',type=Path,required=True);p.add_argument('--proposals',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();fixture=json.loads((a.package_root/'fixture.json').read_text());proposals=json.loads(a.proposals.read_text());by={(r['query_id'],r['candidate_id'],r['image_id'],r['claim_id']):r for r in proposals['records']};claims={c['claim_id']:c for g in fixture['claim_sets'] for c in g['claims']};groups={}
 for expected in fixture['expected_records']:groups.setdefault((expected['query_id'],expected['candidate_id'],expected['image_id']),[]).append(expected)
 articles=[]
 image_root=(a.package_root/'images').resolve();relative_image_root=Path(os.path.relpath(image_root,a.output.parent.resolve())).as_posix()
 for (q,candidate,image),rows in groups.items():
  cards=[]
  for expected in rows:
   proposal=by[(q,candidate,image,expected['claim_id'])];claim=claims[expected['claim_id']];options=''.join(f'<option value="{v}"{" selected" if proposal["proposed_verdict"]==v else ""}>{v}</option>' for v in ('supported','contradicted','unverifiable'));cards.append(f'''<section class="claim" data-claim="{escape(expected['claim_id'],quote=True)}"><p><b>{escape(claim['kind'])}</b>: {escape(json.dumps(claim['value'],ensure_ascii=False))}<br><small>{escape(claim['evidence']['text'])}</small></p><aside><b>Propuesta AI:</b> {escape(proposal['proposed_verdict'])}<br>{escape(proposal['observed_evidence'] or '')}<br>{escape(proposal['justification'])}<br>Limitaciones: {escape(', '.join(proposal['limitations']) or 'ninguna')}</aside><label>Decisión humana<select>{options}</select></label><label>Evidencia humana<textarea maxlength="240">{escape(proposal['observed_evidence'] or '')}</textarea></label><label>Motivo/limitación<textarea class="reason" maxlength="240">{escape(proposal['ambiguity'] or '')}</textarea></label><label><input type="checkbox" class="reviewed"> Revisada por humano</label></section>''')
  articles.append(f'<article data-query="{escape(q,quote=True)}" data-candidate="{escape(candidate,quote=True)}" data-image="{escape(image,quote=True)}"><h2>{escape(q)} · {escape(image)}</h2><img src="{relative_image_root}/{escape(image,quote=True)}.jpg"><div class="grid">{"".join(cards)}</div></article>')
 data=json.dumps(fixture['expected_records'],ensure_ascii=False).replace('</','<\\/');script=r'''<script id="expected" type="application/json">DATA</script><script>const expected=JSON.parse(document.getElementById('expected').textContent);document.getElementById('export').onclick=()=>{try{const reviewer=document.getElementById('reviewer').value.trim();if(!reviewer)throw Error('Falta revisor');const records=[];document.querySelectorAll('article').forEach(a=>a.querySelectorAll('.claim').forEach(c=>{if(!c.querySelector('.reviewed').checked)throw Error('Quedan filas sin revisión humana');const verdict=c.querySelector('select').value,evidence=c.querySelector('textarea').value.trim(),reason=c.querySelector('.reason').value.trim();if(['supported','contradicted'].includes(verdict)&&!evidence)throw Error('support/contradiction necesita evidencia humana');records.push({query_id:a.dataset.query,candidate_id:a.dataset.candidate,image_id:a.dataset.image,claim_id:c.dataset.claim,human_verdict:verdict,observed_evidence:evidence||null,reason:reason||null,review_status:'reviewed',reviewer,reviewed_at_utc:new Date().toISOString()});}));const out={schema_version:'1.0',contract_version:'visual-atomic-human-annotations-v1',instructions:{absence_is_unverifiable:true,one_record_per_claim_image:true,orientation_must_be_externally_comparable:true},records};const u=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)+'\n'],{type:'application/json'})),l=document.createElement('a');l.href=u;l.download='human-reviewed-annotations.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status.textContent='Exportado';}catch(e){status.textContent=e.message;}};</script>'''.replace('DATA',data);html='''<!doctype html><html lang="es"><meta charset="utf-8"><title>Revisión humana de propuestas Codex</title><style>body{font:15px system-ui;max-width:1500px;margin:auto;background:#f4f1e8;padding:1rem}.bar{position:sticky;top:0;background:#183b2d;color:white;padding:1rem;z-index:2}article{border-top:3px solid #1f6f54;padding:1rem}img{max-width:620px;max-height:430px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:.7rem}.claim{background:white;padding:.8rem}.claim aside{background:#eef2ff;padding:.5rem}label{display:block;margin:.5rem 0}select,textarea,input{font:inherit;width:100%;box-sizing:border-box}textarea{min-height:4rem}</style><h1>Revisión humana de propuestas AI</h1><p>La propuesta Codex no es verdad de referencia. Confirma o corrige cada fila.</p><div class="bar">Revisor <input id="reviewer"><button id="export">Exportar anotaciones humanas</button> <span id="status"></span></div>'''+''.join(articles)+script+'</html>';a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(html,encoding='utf-8');print(json.dumps({'output':str(a.output),'records':72},sort_keys=True));return 0
if __name__=='__main__':raise SystemExit(main())
